"use strict";
import ToggleLend from "components/ToggleLend";
import { useMorphoMarkets } from "hooks/morpho";
import { Flex } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { BorrowContextProvider, useBorrowContext } from "./ContextProvider";
import AutoDeleverageConfirmModal from "./components/AutoDeleverageConfirmModal";
import AutoDeleveragePopupModal from "./components/AutoDeleveragePopupModal";
import AutoDeleverageReviewModal from "./components/AutoDeleverageReviewModal";
import BorrowCard from "./components/BorrowCard";
import BorrowConfirmModal from "./components/BorrowConfirmModal";
import BorrowPopupModal from "./components/BorrowPopupModal";
import BorrowReviewModal from "./components/BorrowReviewModal";
import BorrowTable from "./components/BorrowTable";
import BorrowTop from "./components/BorrowTop";
import PositionCard from "./components/PositionCard";
import { PositionTable } from "./components/PositionTable";
import RepayPopupModal from "./components/RepayPopupModal";
import ToggleTab from "./components/ToggleTab";
import UserBorrow from "./components/UserBorrow";
function BorrowContent() {
  const {
    activeTab,
    transactionStep,
    transactionType,
    selectedPosition,
    closeTransaction,
    setTransactionStep,
    collateralAmount,
    borrowAmount
  } = useBorrowContext();
  const chainId = UniverseChainId.Mainnet;
  const { data: markets } = useMorphoMarkets(chainId);
  const collateralToken = selectedPosition?.collateral.token;
  const borrowToken = selectedPosition?.loan.token;
  const marketId = selectedPosition?.id;
  const market = markets?.find((m) => m.id.toLowerCase() === marketId?.toLowerCase());
  const lltvPercent = market?.lltvPercent ?? 86;
  const collateralPrice = market?.collateralPriceUsd ?? 0;
  const borrowPrice = market?.loanPriceUsd ?? 1;
  const collateralBalance = selectedPosition?.collateral.amount ?? 0;
  const borrowBalance = selectedPosition?.loan.amount ?? 0;
  return <Flex
    mt="$spacing24"
    width="100%"
    px="$spacing24"
    maxWidth={1200}
    pb={"$spacing40"}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
  >
      <ToggleLend />
      <UserBorrow />
      <ToggleTab />
      {activeTab === "Markets" && <>
          <BorrowTop />
          <Flex $lg={{ display: "none" }}>
            <BorrowTable />
          </Flex>
          <Flex display="none" $lg={{ display: "block" }}>
            <BorrowCard />
          </Flex>
        </>}
      {activeTab === "Your positions" && <>
          <Flex $lg={{ display: "none" }}>
            <PositionTable />
          </Flex>
          <Flex display="none" $lg={{ display: "block" }}>
            <PositionCard />
          </Flex>
        </>}

      {
    /* Input Modals */
  }
      {transactionStep === "input" && selectedPosition && <>
          {transactionType === "borrow" && <BorrowPopupModal isOpen={true} position={selectedPosition} onClose={closeTransaction} />}
          {transactionType === "repay" && <RepayPopupModal isOpen={true} position={selectedPosition} onClose={closeTransaction} />}
          {transactionType === "autodeleverage" && <AutoDeleveragePopupModal isOpen={true} position={selectedPosition} onClose={closeTransaction} />}
        </>}

      {
    /* Review Modals */
  }
      {transactionStep === "review" && selectedPosition && <>
          {(transactionType === "borrow" || transactionType === "repay") && <BorrowReviewModal
    isOpen={true}
    onClose={closeTransaction}
    onConfirm={() => setTransactionStep("confirm")}
    collateralAmount={collateralAmount}
    borrowAmount={borrowAmount}
    collateralToken={{ ...collateralToken, price: collateralPrice, balance: collateralBalance }}
    borrowToken={{ ...borrowToken, price: borrowPrice, balance: borrowBalance }}
  />}
          {transactionType === "autodeleverage" && <AutoDeleverageReviewModal
    isOpen={true}
    onClose={closeTransaction}
    onConfirm={() => setTransactionStep("confirm")}
    position={selectedPosition}
    autoDeleverageLtv={56.25}
  />}
        </>}

      {
    /* Confirm Modals */
  }
      {transactionStep === "confirm" && selectedPosition && marketId && <>
          {(transactionType === "borrow" || transactionType === "repay") && collateralToken && borrowToken && <BorrowConfirmModal
    isOpen={true}
    onClose={closeTransaction}
    marketId={marketId}
    collateralAmount={collateralAmount}
    borrowAmount={borrowAmount}
    collateralToken={collateralToken}
    borrowToken={borrowToken}
    lltvPercent={lltvPercent}
    transactionType={transactionType}
  />}
          {transactionType === "autodeleverage" && <AutoDeleverageConfirmModal isOpen={true} onClose={closeTransaction} position={selectedPosition} />}
        </>}
    </Flex>;
}
export default function Borrow() {
  return <BorrowContextProvider>
      <BorrowContent />
    </BorrowContextProvider>;
}
